547	// graphNodeName returns the import-graph node for the file currently
548	// being processed. Tokens belonging to a file read from disk carry its
549	// canonical identity in File (set in doSingleImport), so the same real
550	// file reached through an alias or ".." maps to one node. The entry
551	// file's own tokens keep their lexical File (so its diagnostics stay
552	// stable), hence the current file is canonicalized here. The virtual
553	// root of an inline adaptation ("Caddyfile") keeps its lexical name.
554	// Snippet tokens are namespaced by snippet name so importing a snippet
555	// remains distinct from importing its file.
556	func (p *parser) graphNodeName() string {
557		return p.canonicalFileNodeName(p.File(), p.Token().snippetName)
558	}
559	
560	// fileNodeName builds the graph node for a file, optionally namespaced
561	// by snippet name. The file argument is expected to already be the
562	// canonical identity produced when the file was read.
563	func (p *parser) fileNodeName(file, snippet string) string {
564		name := file
565		if snippet != "" {
566			name += fmt.Sprintf(":%s", snippet)
567		}
568		return name
569	}
570	
571	// canonicalFileNodeName is fileNodeName for a lexical file name that may
572	// be an alias: it resolves the file to its canonical identity first. A
573	// name that does not denote a file on disk (the virtual inline root
574	// "Caddyfile", a test-only filename) is used verbatim so those nodes are
575	// not accidentally renamed.
576	func (p *parser) canonicalFileNodeName(file, snippet string) string {
577		name := file
578		if info, err := os.Stat(name); err == nil && info.Mode().IsRegular() {
579			if real, err := p.realPath(name); err == nil {
580				name = real
581			}
582		}
583		return p.fileNodeName(name, snippet)
584	}
585	
586	// resolveFileImports expands an import pattern (a concrete path or a
587	// glob) into the imported tokens. It also returns the canonical
588	// identities of the imported files, for import-cycle tracking.
589	//
590	// Canonical identities are symlink-resolved, absolute, cleaned paths, so
591	// the same physical file reached by different spellings (symlink
592	// aliases, ".." segments, or a mix of absolute and relative paths) is
593	// treated as one file. The lexical path is still used to open the file;
594	// once read, its tokens are anchored to the canonical path, so a file
595	// reached through a symlink resolves its own relative imports against
596	// the file that declares them.
597	//
598	// Within a single glob, a file matched more than once (for example both
599	// a real file and a symlink to it) expands only once, in a deterministic
600	// order based on the canonical path. Explicitly repeated imports are
601	// different statements and keep their own semantics.
602	func (p *parser) resolveFileImports(importPattern string) ([]Token, []string, error) {
603		// make path relative to the file of the _token_ being processed rather
604		// than current working directory (issue #867) and then use glob to get
605		// list of matching filenames. Resolve through symlinks and ".." first:
606		// a relative import declared in a file reached through an alias must
607		// resolve against the directory that actually holds the declaring file,
608		// not the directory the alias lives in.
609		anchorFile, err := p.realPath(p.Dispenser.File())
610		if err != nil {
611			return nil, nil, p.Errf("Failed to get absolute path of file: %s: %v", p.Dispenser.File(), err)
612		}
613	
614		var globPattern string
615		if !filepath.IsAbs(importPattern) {
616			globPattern = filepath.Join(filepath.Dir(anchorFile), importPattern)
617		} else {
618			globPattern = importPattern
619		}
620		if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
621			(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
622			// See issue #2096 - a pattern with many glob expansions can hang for too long
623			return nil, nil, p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
624		}
625		matches, err := filepath.Glob(globPattern)
626		if err != nil {
627			return nil, nil, p.Errf("Failed to use import pattern %s: %v", importPattern, err)
628		}
629		if len(matches) == 0 {
630			if strings.ContainsAny(globPattern, "*?[]") {
631				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
632				return nil, nil, nil
633			}
634			return nil, nil, p.Errf("File to import not found: %s", importPattern)
635		}
636	
637		// See issue #5295 - should skip any files that start with a . when iterating over them.
638		sep := string(filepath.Separator)
639		segGlobPattern := strings.Split(globPattern, sep)
640		if strings.HasPrefix(segGlobPattern[len(segGlobPattern)-1], "*") {
641			var tmpMatches []string
642			for _, m := range matches {
643				seg := strings.Split(m, sep)
644				if !strings.HasPrefix(seg[len(seg)-1], ".") {
645					tmpMatches = append(tmpMatches, m)
646				}
647			}
648			matches = tmpMatches
649		}
650	
651		// A single glob statement may address the same real file more than
652		// once (a file and a symlink alias, two aliases, or equivalent
653		// spellings). Resolve each lexical match to its canonical identity,
654		// drop duplicates, and sort by canonical path so the expansion order
655		// is stable and independent of how the pattern was written or the
656		// order the filesystem returned entries in.
657		type resolvedImport struct {
658			lexical string // path used to read the file and anchor its relative imports
659			real    string // canonical identity used for dedup and cycle tracking
660		}
661		resolved := make([]resolvedImport, 0, len(matches))
662		seen := make(map[string]struct{}, len(matches))
663		for _, match := range matches {
664			realPath, err := p.realPath(match)
665			if err != nil {
666				return nil, nil, p.Errf("Could not resolve import %s: %v", match, err)
667			}
668			if _, dup := seen[realPath]; dup {
669				continue
670			}
671			seen[realPath] = struct{}{}
672			resolved = append(resolved, resolvedImport{lexical: match, real: realPath})
673		}
674		slices.SortFunc(resolved, func(a, b resolvedImport) int {
675			return strings.Compare(a.real, b.real)
676		})
677	
678		var importedTokens []Token
679		nodes := make([]string, 0, len(resolved))
680		for _, imp := range resolved {
681			newTokens, err := p.doSingleImport(imp.lexical)
682			if err != nil {
683				return nil, nil, err
684			}
685			importedTokens = append(importedTokens, newTokens...)
686			nodes = append(nodes, imp.real)
687		}
688	
689		return importedTokens, nodes, nil
690	}
691	
692	// realPath returns the canonical identity of a file path: absolute,
693	// cleaned, symlinks resolved, and spelled as the names exist on disk.
694	// It is used to recognize the same physical file across different
695	// spellings. Results are memoized for the duration of a parse so
696	// repeated adaptation over the same file tree is consistent and avoids
697	// redundant filesystem work.
698	//
699	// Case rules are observed from the running filesystem rather than from
700	// the target operating system: a case-insensitive volume (such as a
701	// default APFS or FAT mount on a Unix-like system) folds names that
702	// differ only in case, while a case-sensitive volume does not. See
703	// canonicalCasePath.
704	//
705	// If a path cannot be fully evaluated (for example a dangling symlink),
706	// it falls back to the cleaned absolute path; the subsequent open in
707	// doSingleImport then reports the underlying I/O error using the
708	// existing error paths.
709	func (p *parser) realPath(path string) (string, error) {
710		if p.realPathCache == nil {
711			p.realPathCache = make(map[string]string)
712		}
713		if cached, ok := p.realPathCache[path]; ok {
714			return cached, nil
715		}
716	
717		abs, err := caddy.FastAbs(path)
718		if err != nil {
719			return "", err
720		}
721	
722		// Resolve symlinks to obtain the real file identity. If the path
723		// cannot be fully evaluated (a dangling symlink, a permission error,
724		// ...), fall back to the cleaned absolute path: the subsequent open
725		// in doSingleImport then reports the underlying I/O error using the
726		// existing error paths, so unreadable imports keep their established
727		// error categories.
728		real := abs
729		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
730			real = filepath.Clean(resolved)
731		}
732	
733		// Fold the spelling the way the live filesystem does, so names
734		// differing only in case on a case-insensitive volume map to one
735		// identity (and are left apart on a case-sensitive one).
736		real = p.canonicalCasePath(real)
737	
738		p.realPathCache[path] = real
739		return real, nil
740	}
741	
742	// canonicalCasePath rewrites each component of an absolute, symlink-resolved
743	// path to the spelling it actually has on disk when the containing directory
744	// folds name case.
745	//
746	// Whether two names differing only in case denote the same file is a property
747	// of the filesystem the path is mounted on, not of the operating system: a
748	// case-insensitive APFS, NTFS or FAT volume folds them even on a Unix kernel,
749	// while a case-sensitive volume keeps distinct names. Rather than assume a
750	// rule per GOOS, each component is probed against the live directory: if the
751	// component has no exact on-disk spelling but stat-ing that spelling resolves
752	// to another entry that differs only in case, the volume folds case and the
753	// on-disk spelling is used. On a case-sensitive volume the stat fails (or
754	// names a different file), so the lexical spelling is left untouched. As soon
755	// as a component cannot be inspected, the remaining components keep their
756	// lexical spelling; such paths then fail through the usual import error
757	// paths.
758	func (p *parser) canonicalCasePath(resolved string) string {
759		sep := string(filepath.Separator)
760		vol := filepath.VolumeName(resolved)
761		rest := strings.TrimPrefix(resolved[len(vol):], sep)
762		components := strings.Split(rest, sep)
763	
764		current := vol
765		if current == "" {
766			current = sep
767		} else {
768			current += sep
769		}
770	
771		for i, comp := range components {
772			if comp == "" || comp == "." || comp == ".." {
773				current = filepath.Join(current, comp)
774				continue
775			}
776	
777			entries, err := p.readDirNames(current)
778			if err != nil {
779				// Cannot canonicalize from here on; keep the rest lexical.
780				return filepath.Join(append([]string{current}, components[i:]...)...)
781			}
782	
783			actual := comp
784			if !slices.Contains(entries, comp) {
785				// No entry with the exact spelling. Only fold when the live
786				// filesystem actually resolves this spelling to a sibling
787				// entry that differs in case alone.
788				if lexicalInfo, err := os.Stat(filepath.Join(current, comp)); err == nil {
789					for _, name := range entries {
790						if !strings.EqualFold(name, comp) {
791							continue
792						}
793						realInfo, err := os.Stat(filepath.Join(current, name))
794						if err == nil && os.SameFile(lexicalInfo, realInfo) {
795							actual = name
796						}
797						break
798					}
799				}
800			}
801			current = filepath.Join(current, actual)
802		}
803	
804		return current
805	}
806	
807	// readDirNames returns the entry names of dir, memoized for the duration of
808	// the parse so canonicalizing many paths in the same tree does not re-read
809	// directories.
810	func (p *parser) readDirNames(dir string) ([]string, error) {
811		if p.dirEntriesCache != nil {
812			if names, ok := p.dirEntriesCache[dir]; ok {
813				return names, nil
814			}
815		}
816		entries, err := os.ReadDir(dir)
817		if err != nil {
818			return nil, err
819		}
820		names := make([]string, 0, len(entries))
821		for _, entry := range entries {
822			names = append(names, entry.Name())
823		}
824		if p.dirEntriesCache == nil {
825			p.dirEntriesCache = make(map[string][]string)
826		}
827		p.dirEntriesCache[dir] = names
828		return names, nil
829	}
830	
831	// doSingleImport lexes the individual file at importFile and returns
832	// its tokens or an error, if any.
833	func (p *parser) doSingleImport(importFile string) ([]Token, error) {
834		// Stat before opening: on some platforms opening certain non-regular
835		// files (a FIFO, for example) blocks until another end shows up, so
836		// opening first could hang the adaptation. os.Stat follows symlinks,
837		// matching the previous open-then-fstat behavior for aliases.
838		info, err := os.Stat(importFile)
839		if err != nil {
840			return nil, p.Errf("Could not import %s: %v", importFile, err)
841		}
842		if info.IsDir() {
843			return nil, p.Errf("Could not import %s: is a directory", importFile)
844		}
845		if info.Mode()&os.ModeType != 0 {
846			// a non-regular file (FIFO, socket, device, ...) is not a
847			// readable Caddyfile; reject it with the directory case's
848			// error wrapping and category
849			return nil, p.Errf("Could not import %s: not a regular file", importFile)
850		}
851	
852		file, err := os.Open(importFile)
853		if err != nil {
854			return nil, p.Errf("Could not import %s: %v", importFile, err)
855		}
856		defer file.Close()
857	
858		input, err := io.ReadAll(file)
859		if err != nil {
860			return nil, p.Errf("Could not read imported file %s: %v", importFile, err)
861		}
862	
863		// only warning in case of empty files
864		if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
865			caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
866			return []Token{}, nil
867		}
868	
869		importedTokens, err := allTokens(importFile, input)
870		if err != nil {
871			return nil, p.Errf("Could not read tokens while importing %s: %v", importFile, err)
872		}
873	
874		// Tack the file path onto these tokens so errors show the imported file's name
875		// (we use full, absolute path to avoid bugs: issue #1892). Use the canonical,
876		// symlink-resolved path: relative imports inside an imported file must resolve
877		// relative to the file that actually declares them, even when it was reached
878		// through a symlink alias or a path containing "..".
879		filename, err := p.realPath(importFile)
880		if err != nil {
881			return nil, p.Errf("Failed to get absolute path of file: %s: %v", importFile, err)
882		}
883		for i := range importedTokens {
884			importedTokens[i].File = filename
885		}
886	
887		return importedTokens, nil
888	}
889	
890	// directive collects tokens until the directive's scope
891	// closes (either end of line or end of curly brace block).
892	// It expects the currently-loaded token to be a directive
893	// (or } that ends a server block). The collected tokens
894	// are loaded into the current server block for later use
895	// by directive setup functions.
896	func (p *parser) directive() error {
897		// a segment is a list of tokens associated with this directive
898		var segment Segment
899	
900		// the directive itself is appended as a relevant token
901		segment = append(segment, p.Token())
902	
903		for p.Next() {
904			if p.Val() == "{" {
905				p.nesting++
906				if !p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
907					return p.Err("Unexpected next token after '{' on same line")
908				}
909				if p.isNewLine() {
910					return p.Err("Unexpected '{' on a new line; did you mean to place the '{' on the previous line?")
911				}
912			} else if p.Val() == "{}" {
913				if p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
914					return p.Err("Unexpected '{}' at end of line")
915				}
916			} else if p.isNewLine() && p.nesting == 0 {
917				p.cursor-- // read too far
918				break
919			} else if p.Val() == "}" && p.nesting > 0 {
920				p.nesting--
921			} else if p.Val() == "}" && p.nesting == 0 {
922				return p.Err("Unexpected '}' because no matching opening brace")
923			} else if p.Val() == "import" && p.isNewLine() {
924				if err := p.doImport(1); err != nil {
925					return err
926				}
927				p.cursor-- // cursor is advanced when we continue, so roll back one more
928				continue
929			}
930	
931			segment = append(segment, p.Token())
932		}
933	
934		p.block.Segments = append(p.block.Segments, segment)
935	
936		if p.nesting > 0 {
937			return p.EOFErr()
938		}
939	
940		return nil
941	}
942	
943	// openCurlyBrace expects the current token to be an
944	// opening curly brace. This acts like an assertion
945	// because it returns an error if the token is not
946	// an opening curly brace. It does NOT advance the token.
947	func (p *parser) openCurlyBrace() error {
948		if p.Val() != "{" {
949			if p.valLooksLikeGlobalOptionsAfterImportedSnippets() {
950				return p.Err("global options block must appear before import directives; move the global options block to the top of the Caddyfile")
951			}
952			return p.SyntaxErr("{")
953		}
954		return nil
955	}
956	
957	func (p *parser) valLooksLikeGlobalOptionsAfterImportedSnippets() bool {
958		if p.Val() != "import" || len(p.block.Keys) == 0 {
959			return false
960		}
961	
962		for _, key := range p.block.Keys {
963			if !strings.HasPrefix(key.Text, "(") || !strings.HasSuffix(key.Text, ")") {
964				return false
965			}
966		}
967	
968		return true
969	}
970	
971	// closeCurlyBrace expects the current token to be
972	// a closing curly brace. This acts like an assertion
973	// because it returns an error if the token is not
974	// a closing curly brace. It does NOT advance the token.
975	func (p *parser) closeCurlyBrace() error {
976		if p.Val() != "}" {
977			return p.SyntaxErr("}")
978		}
979		return nil
980	}
981	
982	func (p *parser) isNamedRoute() (bool, string) {
983		keys := p.block.Keys
984		// A named route block is a single key with parens, prefixed with &.
985		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "&(") && strings.HasSuffix(keys[0].Text, ")") {
986			return true, strings.TrimSuffix(keys[0].Text[2:], ")")
987		}
988		return false, ""
989	}
990	
991	func (p *parser) isSnippet() (bool, string) {
992		keys := p.block.Keys
993		// A snippet block is a single key with parens. Nothing else qualifies.
994		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "(") && strings.HasSuffix(keys[0].Text, ")") {
995			return true, strings.TrimSuffix(keys[0].Text[1:], ")")
996		}
997		return false, ""
998	}
999	
1000	// read and store everything in a block for later replay.
1001	func (p *parser) blockTokens(retainCurlies bool) ([]Token, error) {
1002		// block must have curlies.
1003		err := p.openCurlyBrace()
1004		if err != nil {
1005			return nil, err
1006		}
1007		nesting := 1 // count our own nesting
1008		tokens := []Token{}
1009		if retainCurlies {
1010			tokens = append(tokens, p.Token())
1011		}
1012		for p.Next() {
1013			if p.Val() == "}" {
1014				nesting--
1015				if nesting == 0 {
1016					if retainCurlies {
1017						tokens = append(tokens, p.Token())
1018					}
1019					break
1020				}
1021			}
1022			if p.Val() == "{" {
1023				nesting++
1024			}
1025			tokens = append(tokens, p.tokens[p.cursor])
1026		}
1027		// make sure we're matched up
1028		if nesting != 0 {
1029			return nil, p.SyntaxErr("}")
1030		}
1031		return tokens, nil
1032	}
1033	
1034	// ServerBlock associates any number of keys from the
1035	// head of the server block with tokens, which are
1036	// grouped by segments.
1037	type ServerBlock struct {
1038		HasBraces    bool
1039		Keys         []Token
1040		Segments     []Segment
1041		IsNamedRoute bool
1042	}
1043	
1044	func (sb ServerBlock) GetKeysText() []string {
1045		res := make([]string, 0, len(sb.Keys))
1046		for _, k := range sb.Keys {
1047			res = append(res, k.Text)
1048		}
1049		return res
1050	}
1051	
1052	// DispenseDirective returns a dispenser that contains
1053	// all the tokens in the server block.
1054	func (sb ServerBlock) DispenseDirective(dir string) *Dispenser {
1055		var tokens []Token
1056		for _, seg := range sb.Segments {
1057			if len(seg) > 0 && seg[0].Text == dir {
1058				tokens = append(tokens, seg...)
1059			}
1060		}
1061		return NewDispenser(tokens)
1062	}
1063	
1064	// Segment is a list of tokens which begins with a directive
1065	// and ends at the end of the directive (either at the end of
1066	// the line, or at the end of a block it opens).
1067	type Segment []Token
1068	
1069	// Directive returns the directive name for the segment.
1070	// The directive name is the text of the first token.
1071	func (s Segment) Directive() string {
1072		if len(s) > 0 {
1073			return s[0].Text
1074		}
1075		return ""
1076	}
1077	
1078	// spanOpen and spanClose are used to bound spans that
1079	// contain the name of an environment variable.
1080	var (
1081		spanOpen, spanClose    = []byte{'{', '$'}, []byte{'}'}
1082		envVarDefaultDelimiter = ":"
1083	)
1084

