38	// writeImportFile is a small helper that writes content to a file under
39	// the test's temporary directory, creating parent directories as needed.
40	func writeImportFile(t *testing.T, path, content string) {
41		t.Helper()
42		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
43			t.Fatalf("creating directories for %s: %v", path, err)
44		}
45		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
46			t.Fatalf("writing %s: %v", path, err)
47		}
