50	func symlinkOrSkip(t *testing.T, target, link string) {
51		t.Helper()
52		if err := os.MkdirAll(filepath.Dir(link), 0o755); err != nil {
53			t.Fatalf("creating directories for %s: %v", link, err)
54		}
55		if err := os.Symlink(target, link); err != nil {
56			t.Skipf("creating symlinks is not supported here: %v", err)
57		}
