60	// parseInDir parses body as if it were the root Caddyfile located at
61	// <dir>/Caddyfile, so relative imports resolve inside dir.
62	func parseInDir(t *testing.T, dir, body string) ([]ServerBlock, error) {
63		t.Helper()
64		root := filepath.Join(dir, "Caddyfile")
65		return Parse(root, []byte(body))
