80	// A single glob statement may hit the same regular file through several
81	// matches (the file itself and a symlink alias). It must expand exactly
82	// once, in an order based on the canonical path, and must not be reported
83	// as a cycle.
84	func TestImportGlobDeduplicatesByRealFile(t *testing.T) {
85		dir := t.TempDir()
86		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
87		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
88		symlinkOrSkip(t, filepath.Join(dir, "a.conf"), filepath.Join(dir, "z-alias.conf"))
89	
90		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "*")+"\n")
91		if err != nil {
92			t.Fatalf("expected no error, got: %v", err)
93		}
94	
95		got := blockKeys(blocks)
96		want := []string{"host-a", "host-m"}
97		if strings.Join(got, ",") != strings.Join(want, ",") {
98			t.Errorf("expected %v (each file once, canonical order), got %v", want, got)
99		}
100	}
