121	// Expansion order follows the canonical (real) path, not the order the
122	// filesystem returned matches or the lexical spelling of an alias. Here
123	// the alias sorts first lexically but its target sorts after the other
124	// real file.
125	func TestImportGlobOrderFollowsRealPath(t *testing.T) {
126		dir := t.TempDir()
127		writeImportFile(t, filepath.Join(dir, "real", "zzz.conf"), site("host-zzz"))
128		writeImportFile(t, filepath.Join(dir, "b.conf"), site("host-b"))
129		// "a-link" sorts before "b" lexically, but resolves to real/zzz which
130		// sorts after b by canonical path.
131		symlinkOrSkip(t, filepath.Join(dir, "real", "zzz.conf"), filepath.Join(dir, "a-link.conf"))
132	
133		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "*.conf")+"\n")
134		if err != nil {
135			t.Fatalf("expected no error, got: %v", err)
136		}
