138		got := blockKeys(blocks)
139		want := []string{"host-b", "host-zzz"}
140		if strings.Join(got, ",") != strings.Join(want, ",") {
141			t.Errorf("expected canonical-path order %v, got %v", want, got)
142		}
143	}
