612		dir := t.TempDir()
613		root := filepath.Join(dir, "Caddyfile")
614		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
615		writeImportFile(t, filepath.Join(dir, "cyc.conf"), "import cyc-link.conf\n")
616		symlinkOrSkip(t, filepath.Join(dir, "cyc.conf"), filepath.Join(dir, "cyc-link.conf"))
617	
618		var captured []ServerBlock
619		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
620		failBody := []byte("import " + filepath.Join(dir, "cyc.conf") + "\n")
621		goodBody := []byte("import " + filepath.Join(dir, "a.conf") + "\n")
622	
623		out, _, err := adapter.Adapt(failBody, map[string]any{"filename": root})
624		if err == nil {
625			t.Fatal("expected the first adaptation to fail, got nil")
626		}
627		if out != nil {
628			t.Errorf("expected no partial output on failure, got %d bytes", len(out))
629		}
630		if captured != nil {
631			t.Error("expected Setup not to run on a failed adaptation")
632		}
633		firstErr := err.Error()
634	
635		if out, _, err := adapter.Adapt(goodBody, map[string]any{"filename": root}); err != nil {
636			t.Fatalf("expected a later adaptation to succeed, got: %v", err)
637		} else if len(out) == 0 {
638			t.Error("expected non-empty output from the successful adaptation")
639		}
640		if got := blockKeys(captured); len(got) != 1 || got[0] != "host-a" {
641			t.Errorf("expected [host-a] after recovery, got %v", got)
642		}
643	
644		captured = nil
645		out, _, err = adapter.Adapt(failBody, map[string]any{"filename": root})
646		if err == nil {
647			t.Fatal("expected the repeated failure to fail again, got nil")
648		}
649		if out != nil {
650			t.Errorf("expected no partial output on the repeated failure, got %d bytes", len(out))
651		}
652		if captured != nil {
653			t.Error("expected Setup not to run on the repeated failure")
654		}
655		if err.Error() != firstErr {
656			t.Errorf("expected the identical error chain after success\nwant: %s\ngot:  %s", firstErr, err.Error())
657		}
658	}
659

